import { v4 as uuidv4 } from "uuid";

const Menu = () => {
    return (
        <section class="Menu text-body">
            <ul>
                {list_menu.map((element)=>{
                    return <li><a href={element.link} target="_blank" rel="noopener noreferrer" key= {uuidv4()}>{element.title}</a></li>
                })}
            </ul>
        </section>
    );
}

export default Menu;
